import{_ as t,o,c as a,a2 as r}from"./chunks/framework.CNDaxUod.js";const u=JSON.parse('{"title":"2. Google Cloud and the Chat app","description":"","frontmatter":{},"headers":[],"relativePath":"guide/google-chat-setup.md","filePath":"guide/google-chat-setup.md"}'),n={name:"guide/google-chat-setup.md"};function s(d,e,i,h,c,p){return o(),a("div",null,[...e[0]||(e[0]=[r('<h1 id="_2-google-cloud-and-the-chat-app" tabindex="-1">2. Google Cloud and the Chat app <a class="header-anchor" href="#_2-google-cloud-and-the-chat-app" aria-label="Permalink to &quot;2. Google Cloud and the Chat app&quot;">​</a></h1><p>Step 2 of the <a href="./getting-started.html">setup path</a>. You need AsyncUp running at <code>https://HOST</code> (<a href="./server-setup.html">step 1</a>) and a Google Cloud account in your Workspace. The guided setup at <code>https://HOST/app/setup</code> shows the same steps with copy buttons and a live check at each gate; this page explains them.</p><h2 id="before-you-start-allow-chat-apps" tabindex="-1">Before you start: allow Chat apps <a class="header-anchor" href="#before-you-start-allow-chat-apps" aria-label="Permalink to &quot;Before you start: allow Chat apps&quot;">​</a></h2><p>A Workspace admin must allow people to install Chat apps, or you can&#39;t message the app to verify it (section 3) or add it to a space (step 3). In the Admin console: <strong>Apps → Google Workspace → Google Chat → Chat apps → Allow users to install Chat apps: On</strong> (<a href="https://support.google.com/a/answer/7651360" target="_blank" rel="noreferrer">Google&#39;s help</a>). Allowing installs doesn&#39;t install anything for anyone.</p><h2 id="_1-create-a-cloud-project" tabindex="-1">1. Create a Cloud project <a class="header-anchor" href="#_1-create-a-cloud-project" aria-label="Permalink to &quot;1. Create a Cloud project&quot;">​</a></h2><ol><li>Go to <a href="https://console.cloud.google.com/projectcreate" target="_blank" rel="noreferrer">console.cloud.google.com</a> and create a project, e.g. <code>asyncup</code>. Billing is not required.</li><li>Enable the APIs, under <strong>APIs &amp; Services → Library</strong>: <ul><li><strong>Google Chat API</strong> — required.</li><li><strong>Admin SDK API</strong> — needed for <a href="./directory.html">group rosters and Directory lookups</a>. Enabling it now costs nothing and saves a trip back.</li></ul></li><li>Configure the <strong>OAuth consent screen</strong> as <strong>Internal</strong> (<strong>APIs &amp; Services → OAuth consent screen</strong>; newer consoles call it <em>Google Auth Platform</em>). The Chat app can&#39;t be configured until this exists, and an internal app needs no Google review.</li><li>Note the <strong>project number</strong> from <strong>Cloud overview → Project info</strong>. It&#39;s the digits, not the project ID.</li></ol><p>In the guided setup, paste the project number on <strong>Create a Google Cloud project</strong> and press <strong>Verify</strong>.</p><h2 id="_2-create-a-service-account-and-key" tabindex="-1">2. Create a service account and key <a class="header-anchor" href="#_2-create-a-service-account-and-key" aria-label="Permalink to &quot;2. Create a service account and key&quot;">​</a></h2><ol><li><strong>IAM &amp; Admin → Service accounts → Create service account</strong>, e.g. <code>asyncup</code>. It needs <strong>no project roles</strong>: Chat access comes from the Chat app configuration.</li><li>Open the account → <strong>Keys → Add key → Create new key → JSON</strong>. A file downloads.</li><li>In the guided setup&#39;s <strong>Service account</strong> step, paste the whole file and press <strong>Save and verify key</strong>. The key is encrypted at rest with <code>SECRET_KEY</code>.</li></ol><p>The check calls Google Chat as the app, so before the Chat app is configured (section 3) it may say <strong>Google rejected the key</strong>. That&#39;s expected: the key is saved anyway, and <strong>Continue</strong> works. Come back after section 3 and press <strong>Verify stored key</strong>; it should pass then.</p><p>Keep the service account&#39;s email (<code>asyncup@&lt;project&gt;.iam.gserviceaccount.com</code>): <a href="./directory.html">step 5 of the setup path</a> gives it an admin role.</p><p>The same page has an optional <strong>Calendar out-of-office</strong> switch. Leave it off for now: it needs domain-wide delegation, covered in <a href="./directory.html#calendar-ooo">Calendar out-of-office</a>. Group rosters and user lookups don&#39;t need delegation; they use the <a href="./directory.html#admin-role">admin role</a> from step 5 of the setup path.</p><h2 id="_3-configure-the-chat-app" tabindex="-1">3. Configure the Chat app <a class="header-anchor" href="#_3-configure-the-chat-app" aria-label="Permalink to &quot;3. Configure the Chat app&quot;">​</a></h2><p>Open <strong>APIs &amp; Services → Google Chat API → Configuration</strong> (the guided setup links straight to it). Use these values; the guided setup&#39;s <strong>Configure the Chat app</strong> step shows them with your real host filled in:</p><table tabindex="0"><thead><tr><th>Field</th><th>Value</th></tr></thead><tbody><tr><td>App name</td><td><code>AsyncUp</code> (up to 25 characters)</td></tr><tr><td>Avatar URL</td><td><code>https://HOST/app/logo-256.png</code>, or any square HTTPS PNG/JPEG of 256×256 or more</td></tr><tr><td>Description</td><td><code>Async daily standups for your team</code> (up to 40 characters)</td></tr><tr><td>Build this Chat app as a Google Workspace add-on</td><td>Leave ticked, the console default. Unticking it is permanent</td></tr><tr><td>Enable interactive features</td><td>On</td></tr><tr><td>Functionality</td><td>Tick <strong>Join spaces and group conversations</strong>. Direct messages work regardless</td></tr><tr><td>Connection settings</td><td><strong>HTTP endpoint URL</strong>: <code>https://HOST/chat/events</code></td></tr><tr><td>Authentication Audience</td><td><strong>HTTP endpoint URL</strong></td></tr><tr><td>Commands, link previews</td><td>Leave empty / off. AsyncUp uses @mentions</td></tr><tr><td>Visibility</td><td>Everyone in your domain, or specific people and Google Groups (<a href="./distribution.html">step 4</a>)</td></tr></tbody></table><p>Save. The app status should become <strong>LIVE</strong>.</p><h3 id="the-audience-rule" tabindex="-1">The audience rule <a class="header-anchor" href="#the-audience-rule" aria-label="Permalink to &quot;The audience rule&quot;">​</a></h3><p>AsyncUp refuses every event until it knows which signature to expect, and it fails closed. What it needs depends on how the app is built:</p><table tabindex="0"><thead><tr><th>Chat app type</th><th>Google signs events for</th><th>Store in AsyncUp</th></tr></thead><tbody><tr><td>Workspace add-on (today&#39;s default)</td><td>The endpoint URL, signed by the project&#39;s add-on service account</td><td><strong>Both</strong> the project number and <code>https://HOST/chat/events</code></td></tr><tr><td>Older interaction-event app</td><td>The project number</td><td>The project number</td></tr></tbody></table><p>With both values stored, either kind verifies. The guided setup stores the project number in its first step and the URL with <strong>Save audience</strong> on the Chat app step. In <strong>Settings › Google Chat</strong>, the <strong>Project number</strong> row changes only the number and keeps the URL.</p><h3 id="check-the-connection" tabindex="-1">Check the connection <a class="header-anchor" href="#check-the-connection" aria-label="Permalink to &quot;Check the connection&quot;">​</a></h3><p>On the guided setup&#39;s Chat app step:</p><ol><li>Press <strong>Save audience</strong>. It stores <code>https://HOST/chat/events</code> next to the project number. Without it, an add-on app&#39;s events are refused with <code>401</code>. The button disappears once the URL is stored.</li><li>Press <strong>Start listening</strong>, then send any message to AsyncUp in Google Chat (find it with <strong>+ → Find apps</strong>). The step turns to <strong>Verified</strong> when the first signed event arrives, and <strong>Continue</strong> unlocks.</li></ol><p>If nothing arrives, see <a href="#troubleshooting">Troubleshooting</a>.</p><h2 id="next" tabindex="-1">Next <a class="header-anchor" href="#next" aria-label="Permalink to &quot;Next&quot;">​</a></h2><p><a href="./first-standup.html">Step 3: guided setup and first test</a> — create a standup in a private space and watch a whole run before inviting anyone.</p><h2 id="roster-group" tabindex="-1">Optional: group rosters <a class="header-anchor" href="#roster-group" aria-label="Permalink to &quot;Optional: group rosters {#roster-group}&quot;">​</a></h2><p>Moved to <a href="./directory.html">Directory and group rosters</a>, with the admin role the service account needs.</p><h2 id="calendar-ooo" tabindex="-1">Optional: Calendar out-of-office <a class="header-anchor" href="#calendar-ooo" aria-label="Permalink to &quot;Optional: Calendar out-of-office {#calendar-ooo}&quot;">​</a></h2><p>Moved to <a href="./directory.html#calendar-ooo">Directory and group rosters</a>.</p><h2 id="troubleshooting" tabindex="-1">Troubleshooting <a class="header-anchor" href="#troubleshooting" aria-label="Permalink to &quot;Troubleshooting&quot;">​</a></h2><table tabindex="0"><thead><tr><th>Symptom</th><th>Cause and fix</th></tr></thead><tbody><tr><td><code>401</code> on events, or the guided setup never verifies</td><td>The audience is wrong. Store the project <strong>number</strong> (not the ID) <strong>and</strong>, for an add-on app, <code>https://HOST/chat/events</code>. <code>docker compose logs asyncup</code> names the exact mismatch</td></tr><tr><td>&quot;AsyncUp not responding&quot; in Chat, and nothing reaches the server</td><td>Something in front of the server answered instead. Cloudflare&#39;s Bot Fight Mode is the usual culprit: it challenges Google&#39;s <code>Google-gsuiteaddons</code> requests and can&#39;t be bypassed with a WAF rule on the Free plan, so turn it off for the zone. Any bot challenge, login page or HTML error in front of <code>/chat/events</code> has the same effect</td></tr><tr><td>&quot;AsyncUp not responding&quot;, and the server logs the event</td><td>The app answered with something Chat refused. Check the logs for an error, and that you run a current image</td></tr><tr><td>&quot;Could not load dialog. Either the app is not responding or the response is invalid&quot;</td><td>Same as above for a dialog. Upgrade to a current image (<a href="./operations.html#upgrade">Operations</a>)</td></tr><tr><td>&quot;No DM space with users/…&quot; in logs</td><td>That person can&#39;t receive the bot&#39;s DMs yet. See <a href="./distribution.html">Roll out to your team</a></td></tr><tr><td>No prompts arriving</td><td><code>docker compose logs asyncup</code> logs every run opening and closing. Check the standup&#39;s days, timezone and deadline with <code>status</code></td></tr><tr><td>Replies not threading</td><td>The bot posts with a <code>threadKey</code>, which threads even if the parent failed. Check the space&#39;s history settings</td></tr></tbody></table><p>A <code>POST</code> with an empty JSON body to <code>https://HOST/chat/events</code> proves the app is reachable: before an audience is stored it answers <code>200</code> with a &quot;not connected to Google Chat yet&quot; message, and afterwards <code>401</code>, rejecting the unsigned request. A plain <code>GET</code> returns <code>404</code>; the route is <code>POST</code> only.</p>',33)])])}const g=t(n,[["render",s]]);export{u as __pageData,g as default};
